    public function executeMarcar()
    {
        $marcar = 0;
        $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        $servicio = ServicioPeer::retrieveByPK($this->getRequestParameter('servicio_id'));
        if($servicio->getMarca() == 0 || $servicio->getMarca() != $usuariologuiado)
        {
            $marcar = $usuariologuiado;
        }
        $servicio->setMarca($marcar);
        $servicio->save();        
    }
    
    
