	/**
    * servicioActions::desmarcarTodo()
    * Desmarca todos los servicios marcados por el usuario autenticado
    * @return
    */
	public function desmarcarAllServicio()
    {
        /******************************************************************************************/
        $usuario_id = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        if($usuario_id)
        {
    		$conexion = Propel::getConnection();
    		$consulta = "UPDATE %s SET %s = NULL WHERE %s = ".$usuario_id;
            $sql      = sprintf($consulta, ServicioPeer::TABLE_NAME,ServicioPeer::MARCA, ServicioPeer::MARCA);
            $sentencia = $conexion->prepare($sql);
            $sentencia->execute();
        }		
	    /******************************************************************************************/
	}
    
    

