  /**
   * servicioActions::executeReasignar()
   *
   * @return
   */
    public function executeHistorial()
    {   
    	$servicio = ServicioPeer::retrieveByPk($this->getRequestParameter('servicio_id'));
		$this->ser = $servicio;
        
		$c = new Criteria();
		$c->add(AsignarServicioPeer::SERVICIO_ID, $this->getRequestParameter('servicio_id'));
		$c->addJoin(ServicioPeer::SERVICIO_ID, AsignarServicioPeer::SERVICIO_ID);
		$c->addJoin(UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID, AsignarServicioPeer::ASIGNARSERVICIO_ID);
		$c->addAnd(UsuarioAsignadoSolicitudPeer::ROLUSUARIOASIGNACIONSERVICIO_ID,1);
		
		$x = new Criteria();
		$x->add(AsignarServicioPeer::SERVICIO_ID, $this->getRequestParameter('servicio_id'));
		$x->addJoin(ServicioPeer::SERVICIO_ID, AsignarServicioPeer::SERVICIO_ID);
		$x->addJoin(UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID, AsignarServicioPeer::ASIGNARSERVICIO_ID);
		$x->addAnd(UsuarioAsignadoSolicitudPeer::ROLUSUARIOASIGNACIONSERVICIO_ID,2);
		$resp = UsuarioAsignadoSolicitudPeer::doSelect($x);
		$i = 0;
		$nomb = array();	    
        	foreach ($resp as $result){            			
              $nomb[$i] = $result->getUsuario()->getNombre()." ".$result->getUsuario()->getApellido();
			  $i++;
			  }			              		         
		$this->nomb = $nomb;
				
		$this->parametros .= "&servicio_id=" . $this->getRequestParameter('servicio_id');		
        $pager = new sfPropelPager('UsuarioAsignadoSolicitud', 10);
        $pager->setCriteria($c);        
        $pager->setPage($this->getRequestParameter('page', 1));
        $pager->init();
        $this->pager = $pager;                		  	   
    }
	
