	        $this->parametros .= "&regional_id=" . $this->getRequestParameter('regional_id');
	    }
		//*************************************************************************************
        if ($this->getRequestParameter('serviciotipodevolucion_id')) {
	        $c->add(ServicioPeer::SERVICIOTIPODEVOLUCION_ID, $this->getRequestParameter('serviciotipodevolucion_id'));
	        $this->parametros .= "&serviciotipodevolucion_id=" . $this->getRequestParameter('serviciotipodevolucion_id');
	    }
