		//*************************************************************************************************
        $cadSolicitudes   = $this->getUser()->getAttribute('solicitudes','','servicios');
        $this->list_marcados =  preg_split("/[,]+/",trim($cadSolicitudes), -1, PREG_SPLIT_NO_EMPTY);
