  /**
   * servicioActions::executeShow()
   *
   * @return
   */
    /**
     * Replica, para un registro puntual, la misma jerarquia de permisos que executeList()
     * aplica a la lista (VER_TODOS_LOS_SERVICIOS > VER_SERVICIOS_ENTIDAD > VER_SERVICIOS_REGIONAL
     * > usuario asignado), para distinguir "no existen registros" de "existe pero sin permiso".
     */
    private function usuarioTieneAccesoServicio(Servicio $servicio, $usuario_id)
    {
        if ($this->getUser()->checkPerm('VER_TODOS_LOS_SERVICIOS', $usuario_id)) {
            return true;
        }
        if ($this->getUser()->checkPerm('VER_SERVICIOS_ENTIDAD', $usuario_id)) {
            $entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
            $regional = RegionalPeer::retrieveByPk($servicio->getRegionalId());

            return $regional && $regional->getEntidadId() == $entidad_conectado;
        }
        if ($this->getUser()->checkPerm('VER_SERVICIOS_REGIONAL', $usuario_id)) {
            $regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');

            return $servicio->getRegionalId() == $regional_conectado;
        }
        $c = new Criteria();
        $c->add(ServicioPeer::SERVICIO_ID, $servicio->getPrimaryKey());
        $c->addJoin(ServicioPeer::SERVICIO_ID, AsignarServicioPeer::SERVICIO_ID);
        $c->addJoin(AsignarServicioPeer::ASIGNARSERVICIO_ID, UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID);
        $c->add(UsuarioAsignadoSolicitudPeer::USUARIO_ID, $usuario_id);

        return ServicioPeer::doCount($c) > 0;
    }

    public function executeShow()
    {
    	$currentForm="servicio/show";
		$this->verificaPrilegioCerrar($currentForm); 			
        $this->servicio = ServicioPeer::retrieveByPk($this->getRequestParameter('servicio_id'));
        $this->forward404Unless($this->servicio);
        $usuariologuiado_acceso = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        if (!$this->usuarioTieneAccesoServicio($this->servicio, $usuariologuiado_acceso)) {
          $this->getUser()->setFlash('messages_error', ConsultaPermisoHelper::MSG_SIN_PERMISOS);
          return $this->redirect($this->getRequest()->getScriptName().'/servicio/list');
        }
        //**************************************************************************************
		//echo print_r($this->servicio->getBasicUrlAttach());
		//**************************************************************************************
		$c = new Criteria();
        $c->add(AsignarServicioPeer::SERVICIO_ID,$this->getRequestParameter('servicio_id'));                
        $resp = AsignarServicioPeer::doSelectOne($c);
        //**************************************************************************************
        $a =  new Criteria();
        $a->add(UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID,$resp->getAsignarservicioId());
        $a->add(UsuarioAsignadoSolicitudPeer::ROLUSUARIOASIGNACIONSERVICIO_ID,2);
        $a->add(UsuarioAsignadoSolicitudPeer::ESTA_ASIGNADO,1);		
        $this->asignado = UsuarioAsignadoSolicitudPeer::doSelectOne($a);
		//**************************************************************************************
        $msglist = array();
        if(!empty($this->getRequestParameter('msgintegra'))){
            $status = trim($this->getRequestParameter('msgintegra'));
            if($status == 200){
                $msglist[] = "Se envio notificacion a SGV";
            }elseif($status == 400){
                $msglist[] = "Ocurrio un error al enviar la notificacion a SGV, error de integracion";
            }else{
                $msglist[] = "Ocurrio un error interno en el SGDEA al envar a SGV";
            }
        }
        //**************************************************************************************
        $this->msglist = $msglist;
        $this->forward404Unless($this->servicio);        
    }
    
    public function executeUpdateCom()
	{
        $currentForm = "servicio/create";
        $this->verificaPrilegio($currentForm);
        //************************************************************************************
	    $idModulo = !empty($this->getRequestParameter('modulo_id')) ? trim($this->getRequestParameter('modulo_id')) : null;//modulo genera el servicio
    	$idCom    = !empty($this->getRequestParameter('com_id')) ? trim($this->getRequestParameter('com_id')) : null;//id de la comunicacion
		$dirId    = !empty($this->getRequestParameter('idEntidad')) ? trim($this->getRequestParameter('idEntidad')) : null;//id de la entidad destino
        //**************************************************************************************
        $usuarioservicio_id = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        if(trim($this->getRequestParameter('idUser'))){
            $usuarioservicio_id = trim($this->getRequestParameter('idUser'));
        }else{
            $usuarioservicio_id = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        }
        //**************************************************************************************
        $usuario_servicio = UsuarioPeer::retrieveByPK($usuarioservicio_id);
        //**************************************************************************************
        if($this->getRequestParameter('regional_id')){
            $reg = $this->getRequestParameter('regional_id');
        }else{        	        	
            $reg = $usuario_servicio->getRegionalId();
        }
        //**************************************************************************************
        $tiposervicio_id = trim($this->getRequestParameter('tiposervicio_id')) ? trim($this->getRequestParameter('tiposervicio_id')) : 0;
        $tipo_servicio = TipoServicioPeer::retrieveByPK($tiposervicio_id);
        $estadoservicio_id = 1;
        $dependencia_id = $usuario_servicio->getDependenciaId();
        //**************************************************************************************
        if($tipo_servicio == null){
            $this->forward('servicio', 'createCom');
        }
        //**************************************************************************************
        if($tipo_servicio->getInitIntegracion()){
            $estadoservicio_id = 8;
            $receptor_id = $usuarioservicio_id;
        }elseif($tipo_servicio->getTipoEnvio() == 2){
            $estadoservicio_id = 2;
            $receptor_id = $usuarioservicio_id;
        }elseif($tipo_servicio->getTipoEnvio() == 5){
            $estadoservicio_id = 2;
            $receptor_id = $usuarioservicio_id;
        }else{
            $receptor_id = ServicioPeer::validarReceptor($reg,$dependencia_id,$tiposervicio_id);
        }
        //**************************************************************************************
        if($receptor_id){
            $servicio = new Servicio();
            $servicio->setUsuarioId($usuarioservicio_id);
            $servicio->setPeriodoId(date("Y"));
            $servicio->setRegionalId($reg);
            $servicio->setDirectorioexternoId((!empty($dirId) ? $dirId : null));
            $servicio->setTiposervicioId($tiposervicio_id);
            $servicio->setServicioestadoId($estadoservicio_id);//estaba 3
            $servicio->setFechaCreacion(date("Y-m-d G:i:s"));
            $servicio->setEmpresaMensajeriaId(!empty($this->getRequestParameter('empresa_mensajeria_id')) ? trim($this->getRequestParameter('empresa_mensajeria_id')) : null);
            $servicio->setPrioridadsolicitudservicioId($this->getRequestParameter('prioridadsolicitudservicio_id'));
            $servicio->setDetalle(!empty($this->getRequestParameter('detalle')) ? trim($this->getRequestParameter('detalle')) : null);
            $servicio->setEmailDestino(!empty($this->getRequestParameter('email_destino')) ? trim($this->getRequestParameter('email_destino')) : null);
            $servicio->setFolios(!empty($this->getRequestParameter('folios')) ? trim($this->getRequestParameter('folios')) : 1);
            $servicio->setGuia(!empty($this->getRequestParameter('guia')) ? trim($this->getRequestParameter('guia')) : null);
            $servicio->setFechaEnvioGuia(!empty($this->getRequestParameter('fecha_guia')) ? $this->getRequestParameter('fecha_guia') : null);
            $servicio->setValorGuia(!empty($this->getRequestParameter('valor_guia')) ? $this->getRequestParameter('valor_guia') : null);
            $servicio->setFuncionarioDestino(!empty($this->getRequestParameter('funcionario_destino')) ? trim($this->getRequestParameter('funcionario_destino')) : null);
            $servicio->setCargoDestinatario(!empty($this->getRequestParameter('cargo_destinatario')) ? $this->getRequestParameter('cargo_destinatario') : null);
            $servicio->setDireccionDestinatario(!empty($this->getRequestParameter('direccion_destinatario')) ? trim($this->getRequestParameter('direccion_destinatario')) : null);
            $servicio->setPrefijo(!empty($this->getRequestParameter('prefijo')) ? trim($this->getRequestParameter('prefijo')) : null);
            $servicio->setNumerosCaja(!empty($this->getRequestParameter('numeros_caja')) ? trim($this->getRequestParameter('numeros_caja')) : null);
            $servicio->setNumerosCarpeta(!empty($this->getRequestParameter('numeros_carpeta')) ? trim($this->getRequestParameter('numeros_carpeta')) : null);
            $servicio->setMarconormativoId(!empty($this->getRequestParameter('marconormativo_id')) ? trim($this->getRequestParameter('marconormativo_id')) : null);
            $servicio->setProcesodocorigenId(!empty($this->getRequestParameter('procesodocorigen_id')) ? trim($this->getRequestParameter('procesodocorigen_id')) : null);
            $servicio->setFechaResolucion(!empty($this->getRequestParameter('fecha_resolucion')) ? trim($this->getRequestParameter('fecha_resolucion')) : null);
            $servicio->setNumeroResolucion(!empty($this->getRequestParameter('numero_resolucion')) ? trim($this->getRequestParameter('numero_resolucion')) : null);
            //***************************************************************************************
            $servicio->save();
            //***************************************************************************************
            $numero_radicado = ServicioPeer::getNumRadicacion($reg);
            $radicado = ServicioPeer::executeRadicar($reg,$numero_radicado);
            $servicio->setRadicado($radicado);
            $servicio->setNumeroRadicacion($numero_radicado);
            $servicio->save();
            //***************************************************************************************
            $is_insert_valid = ServicioPeer::asignarServicio($reg, $servicio->getPrimaryKey(),true);
            $modulo_id = !empty($idModulo) ? trim($idModulo) : 7;
            $consecutivocompk = !empty($idCom) ? trim($idCom) : null;
            //***************************************************************************************
            if(!$is_insert_valid){
                ServicioPeer::deleteData(ServicioPeer::TABLE_NAME,ServicioPeer::SERVICIO_ID,$servicio->getPrimaryKey());
                return $this->redirect($this->getRequest()->getScriptName().'/servicio/create?cod_msg=1');
            }else{
                $list_interesado = preg_split("/[,]+/", trim($this->getRequestParameter('idUserInteresados')));
                for($index = 0; $index < count($list_interesado); $index++) {
                    $isAddInteresado = ServicioInteresadosPeer::addNewInteresadoByComId($servicio->getPrimaryKey(),$list_interesado[$index]);
                }
                //***********************************************************************************
                $funcionario_destino = !empty($servicio->getFuncionarioDestino()) ? trim($servicio->getFuncionarioDestino()): null;
                $cargo_destino = !empty($servicio->getCargoDestinatario()) ? trim($servicio->getCargoDestinatario()) : null;
                $direccion_destino = !empty($servicio->getDireccionDestinatario()) ? trim($servicio->getDireccionDestinatario()) : null;
                $this->validarDestinatario($dirId, $funcionario_destino, $cargo_destino, $direccion_destino);
                //***********************************************************************************
                $servicio->setConsecutivocomId($consecutivocompk);
                $servicio->setModuloId($modulo_id);
                $servicio->save();
                //***********************************************************************************
                if(!empty($consecutivocompk) && !empty($modulo_id)){
                    switch($idModulo){
                        case 2: //interna
                            $com_interna = ComInternaPeer::retrieveByPK($consecutivocompk);
                            $dependencia_id = $com_interna->getDependenciaId();
                            if(!empty($com_interna)){
                                //$com_interna->setServicioId($servicio->getPrimaryKey());
                                //$com_interna->save();
                            }
                            break;
                        case 3: //recibida
                            $com_recibida = ComRecibidaPeer::retrieveByPK($consecutivocompk);
                            $dependencia_id = $com_recibida->getDependenciaId();
                            if(!empty($com_recibida)){
                                $com_recibida->setServicioId($servicio->getPrimaryKey());
                                $com_recibida->save();
                            }
                            break;
                        case 4: //enviada
                            $com_enviada = ComEnviadaPeer::retrieveByPK($consecutivocompk);
                            $dependencia_id = $com_enviada->getDependenciaId();
                            if(!empty($com_enviada)){
                                $estadocomenviada_id = 6;
                                $com_enviada->setServicioId($servicio->getPrimaryKey());
                                $com_enviada->setEstadocomenviadaId($estadocomenviada_id);
                                $com_enviada->setNumeroResolucion(($servicio->getNumeroResolucion() ? $servicio->getNumeroResolucion() : $com_enviada->getNumeroResolucion()));
                                $com_enviada->setFechaResolucion(($servicio->getFechaResolucion() ? $servicio->getFechaResolucion() : $com_enviada->getFechaResolucion()));
								//********************************************************************
								if($servicio->getMarconormativoId()){
									$com_enviada->setMarcoNormativo($servicio->getMarcoNormativo()->getDescripcion());
								}
								//********************************************************************
								if($servicio->getProcesodocorigenId()){
									$com_enviada->setSuborigen($servicio->getProcesodocOrigen()->getSuborigen());
								}
								//********************************************************************
                                $com_enviada->save();
                                //********************************************************************
                                EnviadaUsuarioPeer::updateEstados($com_enviada->getPrimaryKey(),$estadocomenviada_id);
                            }
                            break;
                        case 17: //actos administrativos
                            $acto_administrativo = ActoAdministrativoPeer::retrieveByPK($consecutivocompk);
							if(!empty($acto_administrativo)){
								$dependencia_id = $acto_administrativo->getDependenciaId();
								$estadoactoadministrativo_id = 7;
								//********************************************************************
								$actoadmon_servicio = ActoadministrativoServicioPeer::addServicioPkByActoAdmon($servicio->getPrimaryKey(),$acto_administrativo->getPrimaryKey());
                                //********************************************************************
								if($servicio->getMarconormativoId()){
									$acto_administrativo->setMarcoNormativo($servicio->getMarcoNormativo()->getDescripcion());
								}
								//********************************************************************
								if($servicio->getProcesodocorigenId()){
									$acto_administrativo->setSuborigen($servicio->getProcesodocOrigen()->getSuborigen());
								}
								//********************************************************************
								$acto_administrativo->setEstadoactoadministrativoId($estadoactoadministrativo_id);
								$acto_administrativo->save();
								//********************************************************************
								ActoAdministrativoPeer::updateEstadosObj($acto_administrativo->getPrimaryKey(),$estadoactoadministrativo_id);
							}
                            break;
                    }
                }
                //***********************************************************************************
                $msgintegracion = "";
                $msgnotify = null;
                //***********************************************************************************
                $params['coll_interesados'] = $list_interesado;
                $params['dependencia_origen'] = $dependencia_id;
                $resp_integra = $servicio->initIntegraciones($params);
                //***********************************************************************************
                if($resp_integra['code'] == 200){
                    $this->getUser()->setFlash('success_usnotified', "Por favor, revisa la Bítacaora del servicio, para verificar el proceso de integracion realizado, <br>".$resp_integra['message']); 
                }else{
                    $this->getUser()->setFlash('warning_usnotified', "Por favor, revisa la Bítacaora del servicio, para verificar el proceso de integracion realizado, <br>".$resp_integra['message']); 
                }
                //***********************************************************************************
                return $this->redirect($this->getRequest()->getScriptName().'/servicio/show?servicio_id='.$servicio->getPrimaryKey().$msgintegracion . $msgnotify);
            }
		}
        else
        {
            return $this->redirect($this->getRequest()->getScriptName().'/servicio/createCom?error=1&com_id='.$idCom.'&modulo_id='.$idModulo);
        }	                    	
	}
	
    public function executeAdvancedFields()
	{
        $tiposervicio_id = trim($this->getRequestParameter('tiposervicio_id')) ? trim($this->getRequestParameter('tiposervicio_id')) : null;
        $icompk_id = trim($this->getRequestParameter('icompk_id')) ? trim($this->getRequestParameter('icompk_id')) : null;
        $modulo_id = trim($this->getRequestParameter('modulo_id')) ? trim($this->getRequestParameter('modulo_id')) : null;
        //********************************************************************************
        $servicio_id = $this->getRequestParameter('servicio_id') ? trim($this->getRequestParameter('servicio_id')) : null;
        $this->servicio = new Servicio();
        //********************************************************************************
        if(!empty($icompk_id) && !empty($modulo_id)){
            switch ($modulo_id) {
                case ModulesEnable::ActosAdministrativos:
                    $acto_administrativo = ActoAdministrativoPeer::retrieveByPK($icompk_id);
                    if($acto_administrativo != null){
                        $this->servicio->setNumeroResolucion($acto_administrativo->getRadicadoCompuesto());
                        $this->servicio->setFechaResolucion($acto_administrativo->getFechaResolucion("Y-m-d"));
                    }
                    break;
                default:                    
                    break;
            }
        }
        //********************************************************************************
        if($servicio_id != null){
            $this->servicio = ServicioPeer::retrieveByPK($servicio_id);
        }
        //********************************************************************************
        $this->tipo_servicio = TipoServicioPeer::retrieveByPK($tiposervicio_id);
        if(!$this->tipo_servicio->getInitIntegracion()){
            $this->getResponse()->setContentType('application/html');
            return $this->renderText("");
        }
    }

    public function executeUpdateDestinos()
	{		
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$reg = $this->getRegionalFirma($usuariologuiado);
		$servicio   = ServicioPeer::retrieveByPk($this->getRequestParameter('servicio_id'));					
		//*******************************************************************************
        $arrDes = preg_split("/[,]+/",trim($this->getRequestParameter('idEntidad')),-1, PREG_SPLIT_NO_EMPTY); 
		$iterador = count($arrDes) - 1;
		for($i=0; $i < $iterador; $i++){
			$serv = $servicio->copy();
	        $serv->setUsuarioId($usuariologuiado);
	        $serv->setDirectorioexternoId($arrDes[$i]);	        
	        $serv->setRegionalId($reg);
	        $serv->setFechaCreacion(date("Y-m-d G:i:s"));
            //****************************************************************************
            $numero_radicado = ServicioPeer::getNumRadicacion($reg);
            $radicado = ServicioPeer::executeRadicar($reg,$numero_radicado);
            $serv->setRadicado($radicado);
            $serv->setNumeroRadicacion($numero_radicado);
            $serv->save();
            //****************************************************************************
	        ServicioPeer::asignarServicio($reg, $serv->getServicioId());
		}				
		//********************************************************************************
		return $this->redirect($this->getRequest()->getScriptName().'/servicio/list');		
	}
	
