                    $this->funcionario_dir  = trim($com_enviada->getFuncionarioDestino()) ? trim($com_enviada->getFuncionarioDestino()) : trim($result->getDirectorioExterno()->getFuncionario());
                    $this->cargo_dir  = $result->getDirectorioexternoId() ? (trim($result->getDirectorioExterno()->getCargo()) == "" ? "" : trim($result->getDirectorioExterno()->getCargo())) : null;
                    $this->direccion_dir  = $result->getDirectorioexternoId() ? (trim($result->getDirectorioExterno()->getDireccion()) == "" ? "" : trim($result->getDirectorioExterno()->getDireccion())) : null;
                    $this->prefijo_dir  = $result->getDirectorioexternoId() ? (trim($result->getDirectorioExterno()->getPrefijo()) == "" ? "" : trim($result->getDirectorioExterno()->getPrefijo())) : null;
				}
                //*************************************************************************************
				$this->obs = 'Solicitud servicio de comunicaci&oacute;n enviada con radicado: '.$com_enviada->getRadicado();
                //*************************************************************************************
                $list_inteIds = array();$list_names = array();
                foreach (ComEnviadaPeer::getListIntersadosByComId($com_enviada->getPrimaryKey()) as $interesado) {
                    $list_inteIds[] = $interesado->getInteresados()->getPrimaryKey();
                    $list_names[] = trim($interesado->getInteresados()->getNumeroIdentificacion())." - ".trim($interesado->getInteresados()->getNombre());
                    $list_emails[] =  $interesado->getInteresados()->getEmail();
