        //*********************************************************************************************
        $msg_error = "";			
        if($this->getRequestParameter('error')){
           switch($this->getRequestParameter('error'))
           {
            case 1:
                    $msg_error = "Error al radicar receptor del servicio no encontrado!";
            break;
           } 
        }
        $this->msg_error = $msg_error;
        /*****************************************************************************************/
        $this->setTemplate('createCom');
    }

