    /**
    * servicioActions::executeUpdateAsignar()
    *
    * @return
    */
    public function executeUpdateAsignar()
    {		
        $servicio  = ServicioPeer::retrieveByPk($this->getRequestParameter('servicio_id'));
        $servicio->setValorGuia(trim($this->getRequestParameter('valor_guia')));
        //**********************************************************************************************
        $servicio_anterior = $servicio->copy();
      	$idAsignar = AsignarServicioPeer::getLlaveAsignar($servicio->getPrimaryKey());
		$idUser = ServicioPeer::getIdReasignar($idAsignar);
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		//**********************************************************************************************
		$obs_asignar = 	trim($this->getRequestParameter('observaciones'));
		$servicioestado_id = trim($this->getRequestParameter('servicioestado_id'));
		$usuario_asignado = trim($this->getRequestParameter('usuario_id'));
		$valor_guia = trim($this->getRequestParameter('valor_guia'));
		$serviciotipodevolucion_id = trim($this->getRequestParameter('serviciotipodevolucion_id'));
		$observaciones_ejecucion = trim($this->getRequestParameter('observaciones_ejecucion'));
		//**********************************************************************************************
        UsuarioAsignadoSolicitudPeer::updateEstadoAsignado($idAsignar);
        //**********************************************************************************************
		//codigo para establecer el idasignar y el usuario que asigna
		$reAsignar = new UsuarioAsignadoSolicitud();
		$reAsignar->setRolusuarioasignacionservicioId(1);
		$reAsignar->setAsignarservicioId($idAsignar);
		$reAsignar->setUsuarioId($idUser[0]);
		$reAsignar->setEstaAsignado(false);
		$reAsignar->save();
        //**********************************************************************************************
		//codigo para establecer el idasignar y el usuario asignado
		$asignar = new UsuarioAsignadoSolicitud();
		$asignar->setRolusuarioasignacionservicioId(2);
		$asignar->setAsignarservicioId($idAsignar);
		$asignar->setUsuarioId($usuario_asignado);
		$asignar->setEstaAsignado(true);
		$asignar->save();
        //**********************************************************************************************
		//codigo para guardar las observaciones del servicio
        $asignarObs = AsignarServicioPeer::retrieveByPK($idAsignar);
		$asignarObs->setObservaciones($obs_asignar);
		$asignarObs->setValor($valor_guia);
		$asignarObs->save();
		//**********************************************************************************************
		$obs_bitacora = $obs_asignar;
		if($servicioestado_id){
			$servicio->setServicioestadoId($servicioestado_id);
			//******************************************************************************************
			if($serviciotipodevolucion_id){
				$servicio->setServiciotipodevolucionId($serviciotipodevolucion_id);
			}
			//******************************************************************************************
            $servicio->setObsDevolucion($observaciones_ejecucion);            
            $obs_bitacora .= trim($obs_asignar) ? " | " . $observaciones_ejecucion : $observaciones_ejecucion;
		}else{
		    $servicio->setServicioestadoId(2);//2 es asignada
		}
		//**********************************************************************************************
		$servicio->save();
		//**********************************************************************************************
        ServicioPeer::insertBitacoraServicio($servicio->getPrimaryKey(),$servicio->getServicioestadoId(),$usuario_asignado,$usuariologuiado,$obs_bitacora);
		//***********************************************************************************************
        if($servicio->getServicioestadoId() == 3){//estado ejecutado o cerrado
			$cuerpo  = 'Este es un mensaje para informarle que la solicitud de servicio fue ejecutada y cerrada exitosamente: ';
			$servicio->envioEmail($servicio->getUsuarioId(),$observaciones_ejecucion,$cuerpo);
		}elseif($servicio->getServicioestadoId() == 2){
			$cuerpo = 'Este mensaje es para informarle que se le asign&oacute; la siguiente solicitud de servicio:';
			$servicio->envioEmail($usuario_asignado,$obs_asignar,$cuerpo);
		}elseif($servicio->getServicioEstado()->getAddNote()){
            $cuerpo  = 'Este es un mensaje para informarle que la solicitud de servicio fue '.$servicio->getServicioEstado().' y se envio una observaci&oacute;n: ';
            $servicio->envioEmail($servicio->getUsuarioId(),$observaciones_ejecucion, $cuerpo );
        }
		//**********************************************************************************************
        $this->guardarAuditoria($servicio_anterior,$servicio);	  				
        return $this->redirect($this->getRequest()->getScriptName().'/servicio/show?servicio_id='.$servicio->getPrimaryKey());
    }
	
    /**
    * servicioActions::executeUpdateClose()
    *
    * @return
    */
