            //**********************************************************************************************
        }
        $this->guardarAuditoria($servicio_anterior,$servicio);	  				
        return $this->redirect($this->getRequest()->getScriptName().'/servicio/show?servicio_id='.$servicio->getPrimaryKey());
    }

