	public function executeUploadFile()
	{
		$currentForm="SERVICIO_ADJUNTAR_IMAGEN";
		$this->verificaPrilegioCerrar($currentForm); 
		//*********************************************************************************************
		if ($this->getRequest()->hasFiles()){
			$servicio_id = $this->getRequestParameter('servicio_id');
			$file_tmp = $this->getRequest()->getFileName('file');
			$descripcion = trim($this->getRequestParameter('descripcion'));
			$folios = trim($this->getRequestParameter('folios'));
			$observacion_str = "Nuevo Anexo => ".$descripcion;
			$is_error = false;
			//*****************************************************************************************
			if(empty($file_tmp)){
				$this->getRequest()->setError("attachs",'Debe seleccionar un archivo para cargar');
				$is_error = true;
			}
			//*****************************************************************************************
			if(empty($descripcion)){
				$this->getRequest()->setError("descripcion",'Debe digitar la descripcion del anexo');				 
				$is_error = true;
			}
			//*****************************************************************************************
			if($is_error){
				$this->forward('servicio', 'fileImagen');
				//$this->redirect('servicio/fileImagen?servicio_id='.$servicio_id.'&qfile='.md5("nofile"));
			}
			//*****************************************************************************************
			$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
			//*****************************************************************************************
			$servicio = ServicioPeer::retrieveByPk($servicio_id);
			$path_data = $servicio->getBasicUrlAttach();
			//*****************************************************************************************
			$file_vars = pathinfo($file_tmp);
			$util_simad = new simad_util();
			$file_name = $util_simad->clean_name_file($file_vars);
			$directorio = simad_util::createPath($path_data['full_path']);
			$alias_web = ParametroPeer::retrieveByPk(12)->getValortexto();
			$alias_dir = $alias_web.$path_data['basic_path'];
			//*****************************************************************************************
			$cons  = $this->getNewConsecutivo();
			$this->getRequest()->moveFile('file', $directorio.DIRECTORY_SEPARATOR.$cons.'_'.$file_name);
			//*****************************************************************************************
			if(!file_exists($directorio.DIRECTORY_SEPARATOR.$cons.'_'.$file_name)){
				$this->redirect('servicio/fileImagen?servicio_id='.$servicio_id.'&qfile='.md5("exuploadfile"));
			}
			//*****************************************************************************************
			$this->fileName = $cons.'_'.($file_name);
			$datos_archivo = pathinfo(($file_name));
			$this->fileNameOriginal  = trim($datos_archivo['filename']);
			//*****************************************************************************************
			$fileweb = $alias_dir.'/'.$cons.'_'.$file_name;
			//*****************************************************************************************
			ServicioPeer::insertAnexoServicios($servicio_id,$fileweb,$descripcion,$folios,0,0);
			ServicioPeer::insertBitacoraServicio($servicio->getPrimaryKey(),$servicio->getServicioestadoId(),$usuariologuiado,$usuariologuiado,$observacion_str);
            //*****************************************************************************************
            ServicioPeer::saveAnexosExpedientes($servicio_id, $usuariologuiado, $descripcion, $servicio->getTiposervicioId());
		}
	}
    
