  /**
   * servicioActions::executeExcel()
   *
   * @return
   */
    public function executeExcel()
    {
        $this->setLayout(false);
        $this->parametros = '';
        $c = new Criteria();
	    $c->setDistinct();
        $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        //*********************************************************************************************
        if (trim($this->getRequestParameter('porTipoServicio')) != null) {
            $tipo_servicio =  !empty(trim($this->getRequestParameter('porTipoServicio'))) ?  SED::decryption(trim($this->getRequestParameter('porTipoServicio'))) : null;
            $c->addJoin(ServicioPeer::SERVICIO_ID, AsignarServicioPeer::SERVICIO_ID, Criteria::INNER_JOIN);
            $c->addJoin(AsignarServicioPeer::ASIGNARSERVICIO_ID, UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID, Criteria::INNER_JOIN);
            $c->add(ServicioPeer::TIPOSERVICIO_ID, $tipo_servicio);
            $c->add(ServicioPeer::SERVICIOESTADO_ID, array(1, 2, 4), CRITERIA::IN);
            $c->add(UsuarioAsignadoSolicitudPeer::USUARIO_ID, $usuariologuiado);
            $c->add(UsuarioAsignadoSolicitudPeer::ESTA_ASIGNADO, 1);
            $c->add(UsuarioAsignadoSolicitudPeer::ROLUSUARIOASIGNACIONSERVICIO_ID, 2); 

            $this->parametros .= "&porTipoServicio=".trim($this->getRequestParameter('porTipoServicio'));
        }
        //********************************************************************************************
        if ($this->getRequestParameter('periodo_id')) {
	        $c->add(ServicioPeer::PERIODO_ID,$this->getRequestParameter('periodo_id'));
	        $this->parametros .= "&periodo_id=" . $this->getRequestParameter('periodo_id');
	    }else{
	        //$c->add(ServicioPeer::PERIODO_ID,date("Y"));	        
	    }
        
	    if ($this->getRequestParameter('radicado')) {
	        $c->add(ServicioPeer::RADICADO, '%' . $this->getRequestParameter('radicado') .'%', Criteria::LIKE);
	        $this->parametros .= "&radicado=" . $this->getRequestParameter('radicado');
	    }
	
	    if ($this->getRequestParameter('entidad')) {
	        $c->addJoin(ServicioPeer::DIRECTORIOEXTERNO_ID, DirectorioExternoPeer::DIRECTORIOEXTERNO_ID);
	        $c->add(DirectorioExternoPeer::NOMBRE, '%' . $this->getRequestParameter('entidad') .'%', Criteria::LIKE);
	        $this->parametros .= "&entidad=" . $this->getRequestParameter('entidad');
	    }
	
	    if ($this->getRequestParameter('detalle')) {
	        $c->add(ServicioPeer::DETALLE, '%' . $this->getRequestParameter('detalle') . '%',Criteria::LIKE);
	            $this->parametros .= "&detalle=" . $this->getRequestParameter('detalle');
	    }
	
	    if ($this->getRequestParameter('usuario_id')) {
	        $c->add(ServicioPeer::USUARIO_ID, $this->getRequestParameter('usuario_id'));
	        $this->parametros .= "&usuario_id=" . $this->getRequestParameter('usuario_id');
	    }
	
	    if ($this->getRequestParameter('prioridadsolicitudservicio_id')) {
	        $c->add(ServicioPeer::PRIORIDADSOLICITUDSERVICIO_ID, $this->getRequestParameter('prioridadsolicitudservicio_id'));
	        $this->parametros .= "&prioridadsolicitudservicio_id=" . $this->getRequestParameter('prioridadsolicitudservicio_id');
	    }
	    
        if ($this->getRequestParameter('zona_servicio')) {
	        $c->add(ServicioPeer::ZONA_SERVICIO, $this->getRequestParameter('zona_servicio'));
	        $this->parametros .= "&zona_servicio=" . $this->getRequestParameter('zona_servicio');
	    }
        
        if ($this->getRequestParameter('serviciozona_id')) {
	        $c->add(ServicioPeer::SERVICIOZONA_ID, $this->getRequestParameter('serviciozona_id'));
	        $this->parametros .= "&serviciozona_id=" . $this->getRequestParameter('serviciozona_id');
	    }
        
        if ($this->getRequestParameter('marcada')) {		   
			$c->add(ServicioPeer::MARCA,$usuariologuiado);
			$this->parametros .= "&marcada=" . $this->getRequestParameter('marcada');
		}
        
	    if ($this->getRequestParameter('tiposervicio_id')) {
	        $c->add(ServicioPeer::TIPOSERVICIO_ID, $this->getRequestParameter('tiposervicio_id'));
	        $this->parametros .= "&tiposervicio_id=" . $this->getRequestParameter('tiposervicio_id');
	    }
	    
        if ($this->getRequestParameter('regional_id')) {
	        $c->add(ServicioPeer::REGIONAL_ID, $this->getRequestParameter('regional_id'));
	        $this->parametros .= "&regional_id=" . $this->getRequestParameter('regional_id');
	    }
	           
        if($this->getRequestParameter('fechaInicial')){            
           $c->add(ServicioPeer::FECHA_CREACION, str_replace("/","-",$this->getRequestParameter('fechaInicial'))." 00:00:01",Criteria::GREATER_EQUAL);
           $this->parametros .= "&fechaInicial=" . str_replace("/","-",$this->getRequestParameter('fechaInicial'));
        }
	           
        if($this->getRequestParameter('fechaFinal')){
           if($this->getRequestParameter('fechaInicial')){
             $c->addAnd(ServicioPeer::FECHA_CREACION, str_replace("/","-",$this->getRequestParameter('fechaFinal'))." 23:59:59",Criteria::LESS_EQUAL);             
           }else{
             $c->add(ServicioPeer::FECHA_CREACION, str_replace("/","-",$this->getRequestParameter('fechaFinal'))." 23:59:59",Criteria::LESS_EQUAL);
           }
           
           $this->parametros .= "&fechaFinal=" . str_replace("/","-",$this->getRequestParameter('fechaFinal'));
        }
	
	    if ($this->getRequestParameter('servicioestado_id')) {            
	        $c->add(ServicioPeer::SERVICIOESTADO_ID, $this->getRequestParameter('servicioestado_id'));
	        $this->parametros .= "&servicioestado_id=" . $this->getRequestParameter('servicioestado_id');
	    }
	
	    if ($this->getRequestParameter('asignado')) {     
			$c->addJoin(ServicioPeer::SERVICIO_ID,AsignarServicioPeer::SERVICIO_ID);
	        $c->addJoin(AsignarServicioPeer::ASIGNARSERVICIO_ID,UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID);       
	        $c->add(UsuarioAsignadoSolicitudPeer::USUARIO_ID, $this->getRequestParameter('asignado'));	        
	        $c->add(UsuarioAsignadoSolicitudPeer::ESTA_ASIGNADO,1);	        
	        $this->parametros .= "&usuario_id=" . $this->getRequestParameter('usuario_id');
	        
	    }
        /**************************************************************************************/
        $expaddjoin_interesado = false;
        $pnombre_interesado = trim($this->getRequestParameter('pnombre_interesado'));
        if(!empty($pnombre_interesado)){
            $expaddjoin_interesado = true;
            $c->add(InteresadosPeer::PRIMER_NOMBRE,'%'.$pnombre_interesado.'%',Criteria::LIKE);  
            $this->parametros .= "&pnombre_interesado=".$pnombre_interesado;
        }
        /**************************************************************************************/
        $snombre_interesado = trim($this->getRequestParameter('snombre_interesado'));
        if(!empty($snombre_interesado)){
            $expaddjoin_interesado = true;
            $c->add(InteresadosPeer::SEGUNDO_NOMBRE,'%'.$snombre_interesado.'%',Criteria::LIKE);  
            $this->parametros .= "&snombre_interesado=".$snombre_interesado;
        }
        /**************************************************************************************/
        $papellido_interesado = trim($this->getRequestParameter('papellido_interesado'));
        if(!empty($papellido_interesado)){
            $expaddjoin_interesado = true;
            $c->add(InteresadosPeer::PRIMER_APELLIDO,'%'.$papellido_interesado.'%',Criteria::LIKE);  
            $this->parametros .= "&papellido_interesado=".$papellido_interesado;
        }
        /**************************************************************************************/
        $sapellido_interesado = trim($this->getRequestParameter('sapellido_interesado'));
        if(!empty($sapellido_interesado)){
            $expaddjoin_interesado = true;
            $c->add(InteresadosPeer::SEGUNDO_APELLIDO,'%'.$sapellido_interesado.'%',Criteria::LIKE);  
            $this->parametros .= "&sapellido_interesado=".$sapellido_interesado;
        }
        /**************************************************************************************/
        $nuid_interesado = trim($this->getRequestParameter('nuid_interesado'));
        if(!empty($nuid_interesado)){
            $expaddjoin_interesado = true;
            $c->add(InteresadosPeer::NUMERO_IDENTIFICACION,'%'.$nuid_interesado.'%',Criteria::LIKE);  
            $this->parametros .= "&nuid_interesado=".$nuid_interesado;
        }
        /**************************************************************************************/
        if($expaddjoin_interesado){
            $c->addJoin(ServicioPeer::SERVICIO_ID,ServicioInteresadosPeer::SERVICIO_ID);
            $c->addJoin(ServicioInteresadosPeer::INTERESADO_ID,InteresadosPeer::INTERESADO_ID);
        }
        //*************************************************************************************
	    if($this->getRequestParameter('marconormativo_id')) {            
            $c->add(ServicioPeer::MARCONORMATIVO_ID, $this->getRequestParameter('marconormativo_id'));
            $this->parametros .= "&marconormativo_id=" . $this->getRequestParameter('marconormativo_id');
        }
        //*************************************************************************************
        if($this->getRequestParameter('procesodocorigen_id')) {            
            $c->add(ServicioPeer::PROCESODOCORIGEN_ID, $this->getRequestParameter('procesodocorigen_id'));
            $this->parametros .= "&procesodocorigen_id=" . $this->getRequestParameter('procesodocorigen_id');
        }
        //*************************************************************************************
        if(trim($this->getRequestParameter('numero_resolucion'))){
            $c->add(ServicioPeer::NUMERO_RESOLUCION, trim($this->getRequestParameter('numero_resolucion')));
            $this->parametros .= "&numero_resolucion=" . trim($this->getRequestParameter('numero_resolucion'));
        }
        //*************************************************************************************
        if(trim($this->getRequestParameter('fecha_resolucion'))){
            $c->add(ServicioPeer::FECHA_RESOLUCION, trim($this->getRequestParameter('numero_resolucion')).' 00:00:00',Criteria::GREATER_EQUAL);
            $c->addAnd(ServicioPeer::FECHA_RESOLUCION, trim($this->getRequestParameter('numero_resolucion')).' 23:59:59',Criteria::LESS_EQUAL);
            $this->parametros .= "&numero_resolucion=" . trim($this->getRequestParameter('numero_resolucion'));
        }
        //*************************************************************************************
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        if(!$this->getUser()->checkPerm('VER_TODOS_LOS_SERVICIOS', $usuariologuiado)){    
	       //$c->addJoin(ServicioPeer::SERVICIO_ID,AsignarServicioPeer::SERVICIO_ID);
	       //$c->addJoin(AsignarServicioPeer::ASIGNARSERVICIO_ID,UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID);
	       //$c->add(UsuarioAsignadoSolicitudPeer::ESTA_ASIGNADO,1);
		   $c->addJoin(ServicioPeer::SERVICIO_ID,AsignarServicioPeer::SERVICIO_ID);
	       $c->addJoin(AsignarServicioPeer::ASIGNARSERVICIO_ID,UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID);	       		     
	       $c->add(UsuarioAsignadoSolicitudPeer::USUARIO_ID,$usuariologuiado);		             				
		}else{
			//$c->add(UsuarioAsignadoSolicitudPeer::ESTA_ASIGNADO,1);
		}
		$c->addDescendingOrderByColumn(ServicioPeer::SERVICIO_ID);		
		//*************************************************************************************************
        $c->clearSelectColumns();//limpiamos la clausula select        
        //adicionamos las columnas que nesesitamos
        $c->addSelectColumn(ServicioPeer::RADICADO);//0
        $c->addSelectColumn(UsuarioPeer::NOMBRE);//1
        $c->addSelectColumn(UsuarioPeer::APELLIDO);//2        
        $c->addSelectColumn(DirectorioExternoPeer::NOMBRE);//3
        $c->addSelectColumn(ServicioPeer::FECHA_CREACION);//4       
        $c->addSelectColumn(ServicioPeer::SERVICIOESTADO_ID);//5
        $c->addSelectColumn(ServicioEstadoPeer::DESCRIPCION);//6
        $c->addSelectColumn(ServicioPeer::SERVICIO_ID);//7
        $c->addSelectColumn(ServicioPeer::FOLIOS);//8
        $c->addSelectColumn(DirectorioExternoPeer::DIRECCION);//9
        $c->addSelectColumn(ServicioPeer::DETALLE);//10
        //*************************************************************************************************
        //adicionamos los joins
        $c->addJoin(ServicioPeer::DIRECTORIOEXTERNO_ID, DirectorioExternoPeer::DIRECTORIOEXTERNO_ID);
        $c->addJoin(ServicioPeer::USUARIO_ID, UsuarioPeer::USUARIO_ID);
        $c->addJoin(ServicioPeer::SERVICIOESTADO_ID, ServicioEstadoPeer::SERVICIOESTADO_ID);        
        $this->resultset = ServicioPeer::doSelectStmt($c);
		//*************************************************************************************************
    }

