    public function validarDestinatario($directorioexterno_id="",$funcionario="",$cargo="",$direccion="")  
    {
        if(!empty($directorioexterno_id) && !empty($funcionario) && !empty($cargo) && !empty($direccion))
        {
          	$c = new Criteria();
            $c->add(DirectorioExtendedPeer::DIRECTORIOEXTERNO_ID,$directorioexterno_id);
            $c->add(DirectorioExtendedPeer::FUNCIONARIO,$funcionario);
            $c->add(DirectorioExtendedPeer::CARGO,$cargo);
            $c->add(DirectorioExtendedPeer::DIRECCION,$direccion);        
            $count_reg = DirectorioExtendedPeer::doCount($c);
            if(!$count_reg)
            {
                $directorio_extended = new DirectorioExtended();
                $directorio_extended->setDirectorioexternoId($directorioexterno_id);
                $directorio_extended->setFuncionario($funcionario);
                $directorio_extended->setCargo($cargo);
                $directorio_extended->setDireccion($direccion);
                $directorio_extended->save();
            }
        }
    }

    /**
     * servicioActions::getAsignado()
     *
     * @param mixed $idServicio
     * @return
    */
    public function getAsignado($idServicio){
        if(!isset($idServicio)){
            return "";
        }
        /**************************************************************************************************/
        $a = new Criteria();
        $a->add(AsignarServicioPeer::SERVICIO_ID,$idServicio);		
        $res = AsignarServicioPeer::doSelect($a);
        $cont = 0;
        foreach ($res as $val) {
            if ($cont == 0){
                $tempAs = $val->getAsignarservicioId();
            }
            $cont = 1;
        }
        /**************************************************************************************************/
        if(!isset($tempAs)){
            return "";
        }
        /*************************************************************************************************/
        $conexion = Propel::getConnection();
        $consulta = "SELECT MAX(%s) AS max FROM %s where %s=".$tempAs;
        $sql      = sprintf($consulta, UsuarioAsignadoSolicitudPeer::USUARIOASIGNADOSOLICITUD_ID,UsuarioAsignadoSolicitudPeer::TABLE_NAME, UsuarioAsignadoSolicitudPeer::ASIGNARSERVICIO_ID);        		        
        //************************************************************************************
        $sentencia = $conexion->prepare($sql);
        $sentencia->execute();
        $resultset = $sentencia->fetch(PDO::FETCH_OBJ);
        $max = ($resultset->max);
        //************************************************************************************
        $c=new Criteria();
        $c->add(UsuarioAsignadoSolicitudPeer::USUARIOASIGNADOSOLICITUD_ID,$max);		
        $resp =  UsuarioAsignadoSolicitudPeer::doSelect($c);
        $temp = "";
        foreach($resp as $res){		
        $temp = $res->getUsuario()->getNombre()." ".$res->getUsuario()->getApellido();		  			
        }
        //************************************************************************************	    
        return $temp;
    }
    
	public function getNewConsecutivo()
	{
		$cons = ParametroPeer::retrieveByPk(8);
		$regId = $cons->getValorNumerico();
		if($regId > 0){
			$cons->setValorNumerico($regId+1);
			$cons->save();
		}
		return $regId;
	} 
  
    public function uniquename($opendir,$prefix = "plantilla_",$suffix = ".php") 
    {
		$dir_handle = @opendir($opendir) or die("Unable to open $path");

		$max = 0;
		while ($file = readdir($dir_handle)) {
			preg_match("/^$prefix?(.*?)$suffix$/", $file, $treffer);
			$id = $treffer[1];
			if ( $id != "" && $id > $max ) {
				$max = $id;
			}		
		}
		closedir($dir_handle);

		return $prefix . ($max + 1) . $suffix;
	}    
}